// Parse the Slack message text into a structured payload.
// Expected (verbatim) format from Zoom-Slack integration:
//
//   Zoom Recording Completed:
//   Meeting: GLTH Sales & Marketing Meeting
//   Duration: 63 minutes
//   Recording Link: https://us06web.zoom.us/rec/share/...
//
// We tolerate extra whitespace + trailing characters and capture the URL
// up to the next newline / whitespace boundary.

const raw = $input.first().json.text || $input.first().json.message?.text || '';

const meeting = (raw.match(/Meeting:\s*([^\n\r]+)/) || [])[1]?.trim();
const durationStr = (raw.match(/Duration:\s*(\d+)\s*minutes?/i) || [])[1];
const recordingUrl = (raw.match(/Recording\s*Link:\s*(https?:\/\/\S+)/i) || [])[1]?.trim();

if (!meeting || !recordingUrl) {
  throw new Error(`Could not parse Slack message. Got meeting='${meeting}' url='${recordingUrl}'. Raw: ${raw.slice(0, 200)}`);
}

return [{
  json: {
    meeting_name: meeting,
    duration_minutes: durationStr ? Number(durationStr) : null,
    recording_url: recordingUrl,
    source: 'slack:integration-alerts',
    slack_message_ts: $input.first().json.ts || $input.first().json.message?.ts || null,
  },
}];

// Compute HMAC-SHA256 of the raw JSON body. The clawos webhook handler
// verifies sha256 over the EXACT bytes that arrive on the wire, so we
// build the body string here, sign it, then pass both forward to the
// HTTP Request node which sends `body` verbatim and `signature` as a
// header. n8n's HTTP node sends body parameters as JSON when content-type
// is application/json, but the resulting bytes are not always identical
// to JSON.stringify of the source object (key ordering, whitespace),
// which is why we sign+send the same explicit string.

const crypto = require('crypto');

const secret = $env.GLTH_ZOOM_SECRET;
if (!secret) {
  throw new Error('GLTH_ZOOM_SECRET env var not set in n8n. Add it under Settings → Variables.');
}

const payload = $input.first().json;
const body = JSON.stringify({
  meeting_name: payload.meeting_name,
  duration_minutes: payload.duration_minutes,
  recording_url: payload.recording_url,
  source: payload.source,
  slack_message_ts: payload.slack_message_ts,
});

const signature = crypto.createHmac('sha256', secret).update(body).digest('hex');

return [{
  json: {
    body,
    signature: `sha256=${signature}`,
  },
}];
